"""The state of each pipeline run started from the web interface.

Kept in memory and written to files/jobs/ (one JSON file per run), so a restart keeps the outcome of
finished runs. A run still pending or running when the server stopped can no longer finish: the next
start marks it as interrupted.
"""

import json
import os
import re
import threading
from pathlib import Path
from typing import Any, Dict, Optional

from utils.paths import JOBS

# Run ids are generated by the API (8 hex characters); anything else never touches the disk
_RUN_ID = re.compile(r"[0-9A-Za-z_-]{1,64}")

_jobs: Dict[str, Dict[str, Any]] = {}
_lock = threading.Lock()  # the pipeline updates its job from a worker thread


def _file(run_id: str) -> Optional[Path]:
    return JOBS / f"{run_id}.json" if _RUN_ID.fullmatch(run_id) else None


def _save(run_id: str, job: Dict[str, Any]) -> None:
    path = _file(run_id)
    if path is None:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(job), encoding="utf-8")
    os.replace(tmp, path)  # readers never see a half-written file


def create_job(run_id: str) -> None:
    with _lock:
        _jobs[run_id] = {"status": "pending", "html_path": None, "error": None}
        _save(run_id, _jobs[run_id])


def update_job(run_id: str, **kwargs: Any) -> None:
    with _lock:
        if run_id in _jobs:
            _jobs[run_id].update(kwargs)
            _save(run_id, _jobs[run_id])


def get_job(run_id: str) -> Optional[Dict[str, Any]]:
    with _lock:
        if run_id in _jobs:
            return dict(_jobs[run_id])
    path = _file(run_id)
    try:
        return json.loads(path.read_text(encoding="utf-8")) if path else None
    except (OSError, ValueError):
        return None


def mark_interrupted() -> int:
    """At startup: mark the runs the previous process left pending or running. Returns how many."""
    count = 0
    for path in JOBS.glob("*.json"):
        try:
            job = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if job.get("status") in ("pending", "running"):
            job["status"] = "interrupted"
            _save(path.stem, job)
            count += 1
    return count
